ALTER TABLE "receiving_setup_holder" ADD COLUMN "pix_preparation_consent" jsonb;--> statement-breakpoint
ALTER TABLE "receiving_setup_holder" ADD CONSTRAINT "receiving_setup_holder_pix_consent_check" CHECK ("receiving_setup_holder"."pix_preparation_consent" IS NULL OR COALESCE((jsonb_typeof("receiving_setup_holder"."pix_preparation_consent")='object' AND "receiving_setup_holder"."pix_preparation_consent"->>'version'='asaas-incoming-pix-v1' AND "receiving_setup_holder"."pix_preparation_consent"->>'userId'="receiving_setup_holder"."holder_user_id" AND "receiving_setup_holder"."pix_preparation_consent" ?& ARRAY['id','version','accountId','userId','sessionId','authenticatedAt','acceptedAt']),false));